INSERT INTO valuation_company_inputs (ticker, peers_json, targets_json, updated_at) VALUES ('ORCL', '["MSFT","AMZN","GOOGL","META"]', '{"asOf":"2026-10-28","sources":[{"id":"orcl-analyst-meeting-2025-10-16","title":"Oracle expects cloud infrastructure revenue to be $166 bln in FY30 (Reuters, 2025 analyst meeting)","url":"https://www.reuters.com/technology/oracle-expects-cloud-infrastructure-revenue-be-166-bln-fy30-2025-10-16/","date":"2025-10-16"},{"id":"orcl-analyst-meeting-2025-takeaways","title":"Oracle: top 10 takeaways from the 2025 analyst meeting (CreditSights)","url":"https://know.creditsights.com/insights/oracle-top-10-takeaways-from-2025-analyst-meeting/","date":"2025-10-17"},{"id":"orcl-q1-fy27-release","title":"Oracle announces fiscal 2027 first quarter results, driven by triple-digit growth in cloud infrastructure revenues","url":"https://investor.oracle.com/investor-news/news-details/2026/Oracle-Announces-Q1-Results-Driven-by-Triple-Digit-Growth-in-Cloud-Infrastructure-Revenues/default.aspx","date":"2026-09-09"},{"id":"orcl-investor-day-2026","title":"Oracle Investor Day 2026: accelerating value creation (8-K exhibit 99.1)","url":"https://investor.oracle.com/investor-news/news-details/2026/Oracle-Investor-Day-2026-Accelerating-Value-Creation/default.aspx","date":"2026-10-28"},{"id":"orcl-q1-fy27-call","title":"Oracle Q1 FY2027 earnings call transcript","url":"https://stockanalysis.com/stocks/orcl/transcripts/689425-q1-2027/","date":"2026-09-09"},{"id":"orcl-fy25-q4-release","title":"Oracle announces fiscal 2025 fourth quarter and fiscal full year financial results (GAAP and non-GAAP operating income)","url":"https://investor.oracle.com/investor-news/news-details/2025/Oracle-Announces-Fiscal-2025-Fourth-Quarter-and-Fiscal-Full-Year-Financial-Results/default.aspx","date":"2025-06-11"}],"targets":[{"metric":"segment_revenue","segment":"Oracle Cloud Infrastructure","fiscalYear":2026,"value":18000000000,"unit":"currency","basis":"gaap","kind":"target","sourceIds":["orcl-analyst-meeting-2025-10-16","orcl-analyst-meeting-2025-takeaways"]},{"metric":"segment_revenue","segment":"Oracle Cloud Infrastructure","fiscalYear":2027,"value":34000000000,"unit":"currency","basis":"gaap","kind":"derived","sourceIds":["orcl-analyst-meeting-2025-takeaways"],"note":"original FY27 target plus the raises announced at the 2025 analyst meeting"},{"metric":"segment_revenue","segment":"Oracle Cloud Infrastructure","fiscalYear":2028,"value":77000000000,"unit":"currency","basis":"gaap","kind":"derived","sourceIds":["orcl-analyst-meeting-2025-takeaways"],"note":"original FY28 target plus the raises announced at the 2025 analyst meeting"},{"metric":"segment_revenue","segment":"Oracle Cloud Infrastructure","fiscalYear":2029,"value":129000000000,"unit":"currency","basis":"gaap","kind":"derived","sourceIds":["orcl-analyst-meeting-2025-takeaways"],"note":"original FY29 target plus the raises announced at the 2025 analyst meeting"},{"metric":"segment_revenue","segment":"Oracle Cloud Infrastructure","fiscalYear":2030,"value":166000000000,"unit":"currency","basis":"gaap","kind":"target","sourceIds":["orcl-analyst-meeting-2025-10-16"]},{"metric":"revenue","fiscalYear":2027,"value":90000000000,"unit":"currency","basis":"gaap","kind":"floor","sourceIds":["orcl-q1-fy27-release"],"note":"FY27 total revenue of at least $90 billion"},{"metric":"eps","fiscalYear":2027,"value":8.1,"unit":"per_share","basis":"non_gaap","kind":"target","sourceIds":["orcl-q1-fy27-release"]},{"metric":"capex","fiscalYear":2027,"value":92500000000,"unit":"currency","basis":"gaap","kind":"derived","sourceIds":["orcl-q1-fy27-release"],"note":"midpoint of $90–95 billion gross capital expenditure; at most $70 billion net of financing and partner funding"},{"metric":"capex","fiscalYear":2028,"value":92500000000,"unit":"currency","basis":"gaap","kind":"derived","sourceIds":["orcl-investor-day-2026"],"note":"capex peaks in FY27–FY28: FY28 held at the FY27 level; the release gives no FY28 figure"},{"metric":"fcf","fiscalYear":2029,"value":30000000000,"unit":"currency","basis":"gaap","kind":"floor","sourceIds":["orcl-investor-day-2026"],"note":"free cash flow positive in the second half of FY28; FY29 free cash flow of at least $30 billion; capex steps down in FY29"},{"metric":"revenue","fiscalYear":2030,"value":225000000000,"unit":"currency","basis":"gaap","kind":"floor","sourceIds":["orcl-investor-day-2026"],"note":"FY30 total revenue of at least $225 billion"},{"metric":"operating_margin","fiscalYear":2030,"value":0.4,"unit":"ratio","basis":"non_gaap","kind":"floor","sourceIds":["orcl-investor-day-2026"],"note":"non-GAAP operating margin of at least 40%; the calculator''s margin includes stock compensation, so the management case deducts the trailing sbc_ttm / revenue_ttm (FY25: GAAP operating margin 30.8% vs non-GAAP 43.8%, orcl-fy25-q4-release)"},{"metric":"eps","fiscalYear":2030,"value":21,"unit":"per_share","basis":"non_gaap","kind":"floor","sourceIds":["orcl-investor-day-2026"]},{"metric":"rpo","fiscalYear":2027,"value":664000000000,"unit":"currency","basis":"gaap","kind":"target","sourceIds":["orcl-q1-fy27-call"],"note":"remaining performance obligations of $664 billion at 2026-08-31; about half converts to revenue within 36 months"}]}', '2026-11-02T00:00:00.000Z');
